insert into public.projects (slug, category_id, title, label, location, client, description, featured, published, sort)
  select 'the-urban-nest', c.id, $j${"en":"The Urban Nest","de":"The Urban Nest","es":"The Urban Nest"}$j$::jsonb, $j${"en":"Contemporary residential project","de":"Zeitgenössisches Wohnprojekt","es":"Proyecto residencial contemporáneo"}$j$::jsonb, $j${"en":"Netherlands","de":"Niederlande","es":"Países Bajos"}$j$::jsonb, null, $j${"en":"A harmonious fusion of modern living and nature—Urban Oasis Residences is a contemporary residential project designed to integrate greenery seamlessly into urban life. Featuring cascading terraces, lush landscaping, and a soft natural palette, this project reflects a commitment to sustainable architecture and human-centered design.\n\nEach unit embraces natural light, privacy, and a connection to the outdoors, creating a serene environment in the heart of the city. The design prioritizes sustainability with green roofs, energy-efficient materials, and biophilic elements that enhance the well-being of residents.","de":"Eine harmonische Verbindung von modernem Wohnen und Natur: Urban Oasis Residences ist ein zeitgenössisches Wohnprojekt, das Grün nahtlos in das städtische Leben integriert. Kaskadenartige Terrassen, üppige Bepflanzung und eine sanfte, natürliche Farbpalette zeugen von einem klaren Bekenntnis zu nachhaltiger Architektur und menschenzentrierter Gestaltung.\n\nJede Einheit bietet natürliches Licht, Privatsphäre und eine Verbindung zum Außenraum – eine ruhige Umgebung mitten in der Stadt. Nachhaltigkeit steht im Mittelpunkt des Entwurfs: Gründächer, energieeffiziente Materialien und biophile Elemente fördern das Wohlbefinden der Bewohnerinnen und Bewohner.","es":"Una fusión armoniosa entre la vida moderna y la naturaleza: Urban Oasis Residences es un proyecto residencial contemporáneo concebido para integrar la vegetación con naturalidad en la vida urbana. Con terrazas escalonadas, un paisajismo exuberante y una suave paleta de tonos naturales, el proyecto refleja un firme compromiso con la arquitectura sostenible y el diseño centrado en las personas.\n\nCada vivienda aprovecha la luz natural, la privacidad y la conexión con el exterior, creando un entorno sereno en pleno corazón de la ciudad. El diseño da prioridad a la sostenibilidad con cubiertas verdes, materiales de alta eficiencia energética y elementos biofílicos que mejoran el bienestar de sus residentes."}$j$::jsonb, true, true, 10
  from public.categories c where c.slug = 'exterior'
  on conflict (slug) do nothing;
