insert into public.projects (slug, category_id, title, label, location, client, description, featured, published, sort)
  select 'hearthstone-haven', c.id, $j${"en":"Hearthstone Haven","de":"Hearthstone Haven","es":"Hearthstone Haven"}$j$::jsonb, $j${"en":"Interior design project","de":"Interior-Design-Projekt","es":"Proyecto de interiorismo"}$j$::jsonb, $j${"en":"Telemark, Norway","de":"Telemark, Norwegen","es":"Telemark, Noruega"}$j$::jsonb, null, $j${"en":"\"Hearthstone Haven\" is a meticulously crafted interior design project by VARI Studio.\n\nNestled in the serene landscapes of Telemark, Norway,\n\nIt embodies the perfect blend of contemporary elegance and organic textures.\n\nThis design redefines comfort, creating a harmonious space that exudes warmth and tranquility while maintaining a sophisticated aesthetic.","de":"„Hearthstone Haven“ ist ein mit großer Sorgfalt gestaltetes Interior-Design-Projekt von VARI Studio.\n\nEingebettet in die ruhigen Landschaften der Telemark in Norwegen,\n\nvereint es zeitgenössische Eleganz und organische Texturen in vollkommener Balance.\n\nDer Entwurf definiert Komfort neu: ein harmonischer Raum, der Wärme und Ruhe ausstrahlt und zugleich eine anspruchsvolle Ästhetik bewahrt.","es":"«Hearthstone Haven» es un proyecto de interiorismo concebido con esmero por VARI Studio.\n\nEnclavado en los serenos paisajes de Telemark, en Noruega,\n\nencarna la combinación perfecta de elegancia contemporánea y texturas orgánicas.\n\nEl diseño redefine el confort y crea un espacio armonioso que transmite calidez y serenidad sin renunciar a una estética sofisticada."}$j$::jsonb, true, true, 80
  from public.categories c where c.slug = 'interior'
  on conflict (slug) do nothing;
