  select 'timeless-english-roof-architecture', c.id, $j${"en":"Timeless English Roof Architecture","de":"Timeless English Roof Architecture","es":"Timeless English Roof Architecture"}$j$::jsonb, $j${"en":"European-style roofing concept","de":"Dachkonzept im europäischen Stil","es":"Concepto de cubierta de estilo europeo"}$j$::jsonb, $j${}$j$::jsonb, null, $j${"en":"This project explores a sophisticated European-style roofing concept, blending elements from French Provincial and English Tudor architecture.\n\nThe design highlights intricate craftsmanship, high-quality materials, and a seamless fusion of tradition with contemporary construction techniques.","de":"Dieses Projekt entwickelt ein anspruchsvolles Dachkonzept im europäischen Stil, das Elemente der französischen Provinzarchitektur und des englischen Tudorstils verbindet.\n\nDer Entwurf betont kunstvolle Handwerksarbeit, hochwertige Materialien und eine nahtlose Verbindung von Tradition und zeitgemäßen Bautechniken.","es":"Este proyecto explora un sofisticado concepto de cubierta de estilo europeo que combina elementos de la arquitectura provenzal francesa y del estilo Tudor inglés.\n\nEl diseño pone en valor una artesanía minuciosa, materiales de primera calidad y una fusión impecable entre la tradición y las técnicas constructivas contemporáneas."}$j$::jsonb, true, true, 110
  from public.categories c where c.slug = 'interior'
  on conflict (slug) do nothing;
