insert into public.projects (slug, category_id, title, label, location, client, description, featured, published, sort)
  select 'sophisticated-home-office', c.id, $j${"en":"Sophisticated Home Office Design","de":"Sophisticated Home Office Design","es":"Sophisticated Home Office Design"}$j$::jsonb, $j${"en":"Home office","de":"Arbeitszimmer","es":"Despacho en casa"}$j$::jsonb, $j${}$j$::jsonb, null, $j${"en":"A bold and refined home office that merges luxury, creativity, and functionality.\n\nThe statement glossy blue desk contrasts beautifully with the rich textures of metallic and leather accent chairs, creating a space that is both professional and artistic.\n\nThe backdrop features plaid-patterned wallpaper and black wainscoting, adding depth and elegance. Large black-framed windows invite natural light, enhancing the ambiance.\n\nThoughtfully curated chess-themed artwork reinforces a theme of strategy and intellect.\n\nA leopard-print rug introduces an unexpected yet harmonious contrast, making this space a true blend of modern sophistication and timeless style.","de":"Ein mutiges und raffiniertes Arbeitszimmer, das Luxus, Kreativität und Funktionalität vereint.\n\nDer glänzend blaue Schreibtisch als Blickfang kontrastiert wunderbar mit den reichen Texturen der Akzentsessel aus Metall und Leder – ein Raum, der zugleich professionell und künstlerisch wirkt.\n\nDen Hintergrund bilden eine Tapete mit Karomuster und eine schwarze Wandvertäfelung, die Tiefe und Eleganz verleihen. Große, schwarz gerahmte Fenster lassen Tageslicht herein und unterstreichen die Atmosphäre.\n\nSorgfältig ausgewählte Kunstwerke mit Schachmotiven greifen das Thema Strategie und Intellekt auf.\n\nEin Teppich mit Leopardenmuster setzt einen unerwarteten und doch harmonischen Kontrast – so verbindet dieser Raum moderne Raffinesse mit zeitlosem Stil.","es":"Un despacho en casa audaz y refinado que fusiona lujo, creatividad y funcionalidad.\n\nEl llamativo escritorio azul lacado contrasta de forma espectacular con las ricas texturas de los sillones auxiliares de metal y cuero, creando un espacio a la vez profesional y artístico.\n\nComo telón de fondo, un papel pintado de cuadros y un arrimadero negro aportan profundidad y elegancia. Los amplios ventanales con marcos negros dejan entrar la luz natural y realzan el ambiente.\n\nUna cuidada selección de obras de arte con motivos de ajedrez refuerza la idea de estrategia e intelecto.\n\nUna alfombra con estampado de leopardo introduce un contraste inesperado pero armonioso y convierte este espacio en una auténtica combinación de sofisticación moderna y estilo atemporal."}$j$::jsonb, true, true, 190
  from public.categories c where c.slug = 'interior'
  on conflict (slug) do nothing;
