  select pr.id, me.id, 0 from public.projects pr, public.media me where pr.slug = 'sophisticated-home-office' and me.source = 'wix' and me.path = 'b80319_3dcc1d8eb6814b7f91a14dc472afcb62~mv2.png'
  on conflict do nothing;
